/**
 * Pattern icons (base64-encoded PNGs) — bundled into the dashboard HTML so the
 * MCP HTTP server doesn't need to serve any static files. Source PNGs live in
 * the design preview at /tmp/daobrew-preview/icons/, copied here at build time.
 */

import { Element } from "./types.js";

const PREFIX = "data:image/png;base64,";

const tension_b64 = "";

const overdrive_b64 = "";

const stagnation_b64 = "";

const constriction_b64 = "";

const depletion_b64 = "";

export const PATTERN_ICON_DATA_URL: Record<Element, string> = {
  wood:  PREFIX + tension_b64,
  fire:  PREFIX + overdrive_b64,
  earth: PREFIX + stagnation_b64,
  metal: PREFIX + constriction_b64,
  water: PREFIX + depletion_b64,
};
